#include <moppe/site/genesis.hh>

// Generated by luv-shaderc from shaders/genesis.lisp.
#include <genesis_sky.hh>
#include <genesis_terrain.hh>

#include <algorithm>
#include <cmath>
#include <cstddef>
#include <vector>

namespace moppe::site {
  using Frame = nhal::shaders::genesis_terrain::Frame;
  static_assert (sizeof (Frame) == sizeof (nhal::shaders::genesis_sky::Frame));

  namespace {
    constexpr std::uint32_t samples = 4;
    // The page's paper (moppe/site/index.html's --paper, #f3efe4).
    constexpr std::array<float, 4> paper { 0.953f, 0.937f, 0.894f, 1.0f };
    // A morning sun in the south-east, a third of the way up.
    constexpr float sun_azimuth = 2.3f, sun_elevation = 0.5f;

    struct Vec3 {
      float x = 0, y = 0, z = 0;
      Vec3 operator- (Vec3 o) const {
        return { x - o.x, y - o.y, z - o.z };
      }
      Vec3 operator* (float s) const {
        return { x * s, y * s, z * s };
      }
    };

    float dot (Vec3 a, Vec3 b) {
      return a.x * b.x + a.y * b.y + a.z * b.z;
    }
    Vec3 cross (Vec3 a, Vec3 b) {
      return { a.y * b.z - a.z * b.y,
               a.z * b.x - a.x * b.z,
               a.x * b.y - a.y * b.x };
    }
    Vec3 normalize (Vec3 v) {
      return v * (1.0f / std::sqrt (dot (v, v)));
    }
    std::array<float, 4> lanes (Vec3 v, float w) {
      return { v.x, v.y, v.z, w };
    }

    float smooth (float low, float high, float value) {
      const float t = std::clamp ((value - low) / (high - low), 0.0f, 1.0f);
      return t * t * (3.0f - 2.0f * t);
    }

    float mix (float a, float b, float t) {
      return a + (b - a) * t;
    }
  }

  GenesisView
  genesis_choreography (float progress, double seconds, float aspect) {
    const float t = std::clamp (progress, 0.0f, 1.0f);
    GenesisView view;
    view.fov_y = 0.75f;
    // Straight down at the map, tipping to a relief model seen from on
    // high, then down over the land toward the horizon.
    const float tip = smooth (0.15f, 0.55f, t);
    const float lower = smooth (0.55f, 0.95f, t);
    view.pitch = mix (mix (1.56f, 0.85f, tip), 0.26f, lower);
    // From overhead some 2.6 km of the land fill the width, however
    // narrow the screen.
    const float overhead = std::clamp (
      1300.0f / (std::tan (0.5f * view.fov_y) * std::min (aspect, 1.6f)),
      2500.0f,
      9000.0f);
    view.distance = mix (mix (overhead, 3400.0f, tip), 2300.0f, lower);
    view.heading = 0.25f + 0.9f * t + static_cast<float> (seconds) * 0.01f;
    view.exaggeration = mix (1.0f, 1.8f, smooth (0.2f, 0.6f, t));
    view.target = { 2500.0f, 150.0f * view.exaggeration, 2500.0f };
    view.map = 1.0f - smooth (0.18f, 0.42f, t);
    view.land = smooth (0.58f, 0.74f, t);
    view.relief = std::max (0.0f, 1.0f - view.map - view.land);
    view.wire =
      0.8f * smooth (0.25f, 0.38f, t) * (1.0f - smooth (0.42f, 0.58f, t));
    view.seconds = seconds;
    return view;
  }

  Genesis::Genesis (nhal::Device& device,
                    const GenesisShaders& shaders,
                    int lattice,
                    float period_m,
                    float sea_level_m)
      : m_device (device), m_lattice (lattice), m_period (period_m),
        m_sea_level (sea_level_m) {
    const auto side = static_cast<std::uint32_t> (lattice);
    m_samples = device.create_buffer (
      { .size = std::uint64_t (side) * side * 16, .label = "genesis samples" });
    // A vertex past the last sample on each side closes the tile onto the
    // next one; the vertex stage wraps it to the first.
    const std::uint32_t across = side + 1;
    std::vector<std::uint32_t> indices;
    indices.reserve (std::size_t (side) * side * 6);
    for (std::uint32_t z = 0; z < side; ++z)
      for (std::uint32_t x = 0; x < side; ++x) {
        const std::uint32_t a = z * across + x, b = a + 1, c = a + across,
                            d = c + 1;
        indices.insert (indices.end (), { a, c, b, b, c, d });
      }
    m_index_count = std::uint32_t (indices.size ());
    m_indices = device.create_buffer (
      { .size = indices.size () * 4, .label = "genesis indices" },
      std::as_bytes (std::span (indices)));

    nhal::RenderPipelineDesc desc;
    desc.color_formats[0] = device.surface_format ();
    desc.depth_format = nhal::Format::d32_float;
    desc.samples = samples;
    desc.program = &nhal::shaders::genesis_terrain::program;
    desc.vertex = shaders.terrain_vertex;
    desc.fragment = shaders.terrain_fragment;
    desc.label = "genesis terrain";
    m_terrain = device.create_render_pipeline (desc);
    desc.program = &nhal::shaders::genesis_sky::program;
    desc.vertex = shaders.sky_vertex;
    desc.fragment = shaders.sky_fragment;
    desc.depth_write = false;
    desc.label = "genesis sky";
    m_sky = device.create_render_pipeline (desc);
  }

  Genesis::~Genesis () {
    m_device.wait_idle ();
    for (nhal::Texture t : { m_color, m_depth })
      if (t)
        m_device.destroy (t);
    m_device.destroy (m_samples);
    m_device.destroy (m_indices);
    m_device.destroy (m_terrain);
    m_device.destroy (m_sky);
  }

  void Genesis::set_heights (std::span<const float> from,
                             std::span<const float> to) {
    m_staged.resize (from.size ());
    for (std::size_t i = 0; i < from.size (); ++i)
      m_staged[i] = { from[i], to[i], 0.0f, 0.0f };
    m_dirty = true;
  }

  void Genesis::make_targets () {
    for (nhal::Texture t : { m_color, m_depth })
      if (t)
        m_device.destroy (t);
    m_width = m_device.surface_width ();
    m_height = m_device.surface_height ();
    m_color = m_device.create_texture ({ m_width,
                                         m_height,
                                         m_device.surface_format (),
                                         nhal::usage_render_target,
                                         samples,
                                         "genesis samples" });
    m_depth = m_device.create_texture ({ m_width,
                                         m_height,
                                         nhal::Format::d32_float,
                                         nhal::usage_depth,
                                         samples,
                                         "genesis depth" });
  }

  bool Genesis::render (const GenesisView& view, float mix) {
    if (!m_device.begin_frame ())
      return false;
    if (m_width != m_device.surface_width () ||
        m_height != m_device.surface_height ())
      make_targets ();
    if (m_dirty) {
      m_device.copy_to_buffer (
        m_samples,
        0,
        m_device.upload (std::span<const std::array<float, 4>> (m_staged)));
      m_dirty = false;
    }

    const float aspect = float (m_width) / float (m_height);
    const float pitch = std::clamp (view.pitch, -1.5f, 1.56f);
    const Vec3 forward { std::cos (pitch) * std::sin (view.heading),
                         -std::sin (pitch),
                         -std::cos (pitch) * std::cos (view.heading) };
    const Vec3 right = normalize (cross (forward, { 0.0f, 1.0f, 0.0f }));
    const Vec3 up = cross (right, forward);
    const Vec3 target { view.target[0], view.target[1], view.target[2] };
    const Vec3 eye = target - forward * view.distance;
    const float tan_y = std::tan (0.5f * view.fov_y);
    const float tan_x = tan_y * aspect;
    const Vec3 sun { std::sin (sun_azimuth) * std::cos (sun_elevation),
                     std::sin (sun_elevation),
                     -std::cos (sun_azimuth) * std::cos (sun_elevation) };

    Frame frame {};
    frame.eye = lanes (eye, float (std::fmod (view.seconds, 100000.0)));
    frame.right = lanes (right * (1.0f / tan_x), tan_x);
    frame.up = lanes (up * (1.0f / tan_y), tan_y);
    frame.forward = lanes (forward, 2.0f);
    frame.sun = lanes (sun, 0.0f);
    frame.grid = {
      m_period / float (m_lattice), float (m_lattice), m_period, 3.0f
    };
    frame.look = { view.map, view.relief, view.wire, view.land };
    frame.water = {
      m_sea_level, 20.0f, std::clamp (mix, 0.0f, 1.0f), view.exaggeration
    };
    frame.paper = paper;
    frame.zenith = { 0.36f, 0.54f, 0.80f, 1.0f };
    // Fog thickens as the map becomes land and the horizon comes into
    // view, which hides where the tiles end.
    frame.horizon = { 0.80f, 0.85f, 0.89f, 0.00002f + 0.00006f * view.land };

    nhal::RenderPassDesc pass;
    pass.colors[0] = { .texture = m_color,
                       .load = nhal::Load::clear,
                       .store = nhal::Store::discard,
                       .clear = paper,
                       .resolve = m_device.backbuffer () };
    pass.color_count = 1;
    pass.depth = { .texture = m_depth };
    pass.label = "genesis";
    m_device.begin_render_pass (pass);
    m_device.set_viewport (0, 0, float (m_width), float (m_height));
    m_device.set_pipeline (m_terrain);
    m_device.set_uniforms (0, frame);
    m_device.set_buffer (1, m_samples);
    m_device.draw_indexed (
      m_indices, nhal::IndexType::uint32, m_index_count, 9);
    m_device.set_pipeline (m_sky);
    m_device.set_uniforms (0, frame);
    m_device.draw (3);
    m_device.end_render_pass ();
    return true;
  }
}
